content:
650                       DPRINTF(("Out of bounds reading short sector chain "
   651                           "%" SIZE_T_FORMAT "u > %" SIZE_T_FORMAT "u\n",
   652                           i, scn->sst_len));
   653                       goto out;
   654                  }
   655                  if (cdf_read_short_sector(sst, scn->sst_tab, i * ss, ss, h,
   656                      sid) != CAST(ssize_t, ss)) {
   657                       DPRINTF(("Reading short sector chain %d", sid));
   658                       goto out;
   659                  }
   660                  sid = CDF_TOLE4(CAST(uint32_t, ssat->sat_tab[sid]));
   661          }
   662          return 0;
   663  out:
   664          errno = EFTYPE;
   665          return cdf_zero_stream(scn);
   666  }
