   779  int
   780  cdf_read_short_stream(const cdf_info_t *info, const cdf_header_t *h,
   781      const cdf_sat_t *sat, const cdf_dir_t *dir, cdf_stream_t *scn,
   782      const cdf_directory_t **root)
   783  {
   784          size_t i;
   785          const cdf_directory_t *d;
   786
   787          *root = NULL;
   788          for (i = 0; i < dir->dir_len; i++)
   789                  if (dir->dir_tab[i].d_type == CDF_DIR_TYPE_ROOT_STORAGE)
   790                       break;
   791
   792          /* If the it is not there, just fake it; some docs don't have it */
   793          if (i == dir->dir_len) {
   794                  DPRINTF(("Cannot find root storage dir\n"));
   795                  goto out;
   796          }
   797          d = &dir->dir_tab[i];
   798          *root = d;
   799
   800          /* If the it is not there, just fake it; some docs don't have it */
   801          if (d->d_stream_first_sector < 0) {
   802                  DPRINTF(("No first secror in dir\n"));
   803                  goto out;
   804          }
   805
   806          return cdf_read_long_sector_chain(info, h, sat,
   807              d->d_stream_first_sector, d->d_size, scn);
   808  out:
   809          scn->sst_tab = NULL;
   810          (void)cdf_zero_stream(scn);
   811          return 0;
   812  }
